class RuleOfFive {
    int* data = new int(0);

public:
    // 1. Destructor (Cleanup)
    ~RuleOfFive() { delete data; }

    // 2. Copy Constructor (Deep Copy)
    RuleOfFive(const RuleOfFive& other)
        : data(new int(*other.data)) {}

    // 3. Copy Assignment (Handle Cleanup/Self-Assign)
    RuleOfFive& operator=(const RuleOfFive& other) {
        delete data; data = new int(*other.data);
        return *this;
    }

    // 4. Move Constructor (Steal Resource)
    RuleOfFive(RuleOfFive&& temp) noexcept
        : data(temp.data) { temp.data = nullptr; }

    // 5. Move Assignment (Cleanup/Steal)
    RuleOfFive& operator=(RuleOfFive&& temp) noexcept {
        delete data;
        data = temp.data;
        temp.data = nullptr;
        return *this;
    }
};
